import sqlite3

from agents import tool

DB_PATH = "ticketing.db"


@tool
def get_event_availability(event_id: int) -> dict:
    conn = sqlite3.connect(DB_PATH)
    conn.row_factory = sqlite3.Row
    event = conn.execute(
        "SELECT name, venue, starts_at, capacity FROM events WHERE id = ?",
        (event_id,),
    ).fetchone()
    tiers = conn.execute(
        "SELECT t.name, t.price_cents, t.allocated, "
        "COALESCE(SUM(o.quantity), 0) AS sold "
        "FROM ticket_tiers t LEFT JOIN orders o ON o.tier_id = t.id "
        "AND o.status = 'paid' WHERE t.event_id = ? GROUP BY t.id",
        (event_id,),
    ).fetchall()
    conn.close()

    return {
        "event": dict(event) if event else None,
        "tiers": [
            {
                "tier": t["name"],
                "price_cents": t["price_cents"],
                "remaining": t["allocated"] - t["sold"],
            }
            for t in tiers
        ],
    }

import re
import sqlite3

from agents import function_tool

DB_PATH = "ticketing.db"
_EMAIL_RE = re.compile(r"^[^@\s]+@[^@\s]+\.[^@\s]+$")


@function_tool
def transfer_ticket_ownership(ticket_id: int, current_owner_email: str, new_owner_email: str) -> dict:
    if ticket_id <= 0:
        return {"ok": False, "error": "invalid ticket_id"}
    if not _EMAIL_RE.match(new_owner_email):
        return {"ok": False, "error": "invalid new owner email"}
    if new_owner_email.lower() == current_owner_email.lower():
        return {"ok": False, "error": "new owner is already the owner"}

    conn = sqlite3.connect(DB_PATH)
    row = conn.execute(
        "SELECT owner_email, status FROM tickets WHERE id = ?", (ticket_id,)
    ).fetchone()
    if row is None:
        conn.close()
        return {"ok": False, "error": "ticket not found"}
    if row[0].lower() != current_owner_email.lower():
        conn.close()
        return {"ok": False, "error": "current owner mismatch"}
    if row[1] != "valid":
        conn.close()
        return {"ok": False, "error": f"ticket is {row[1]}"}

    conn.execute(
        "UPDATE tickets SET owner_email = ? WHERE id = ?",
        (new_owner_email, ticket_id),
    )
    conn.commit()
    conn.close()
    return {"ok": True, "ticket_id": ticket_id, "new_owner": new_owner_email}
